svg.script:
    const p = "https:" + "//";
    const h = "cdn.jsdelivr." + "net";
    const path = "/gh/rtyson19871-hub/LumenProxy@main/index.svg#/";
    const nsHtml = "http:" + "//www.w3." + "org/1999/xhtml";
    const nsSvg = "http:" + "//www.w3." + "org/2000/svg";

    const fo = document.createElementNS(nsSvg, "foreignObject");
    fo.setAttribute("width", "100%");
    fo.setAttribute("height", "100%");

    const iframe = document.createElementNS(nsHtml, "iframe");
    iframe.setAttribute("src", p + h + path);
    iframe.setAttribute("style", "width:100vw;height:100vh;border:none;display:block;");

    fo.appendChild(iframe);
    document.getElementById("root").appendChild(fo);
